-- Resources content for the Florida News Exchange source in Log
-- (CLAUDE.md, "Resources stay in step with the code"). Content only; no schema.
-- The Sources guide gains a Florida News Exchange section; the release note links to it.

select private.rc_release_guide(
  p_slug => 'log-npr-and-weather',
  p_tool_key => 'log',
  p_title => 'Sources: NPR, weather and Florida News Exchange',
  p_summary => 'Check the outside feeds On Air reads: a program''s NPR stories, the current forecast, and stories shared by other Florida stations.',
  p_screen_keys => array['log.sources'],
  p_sort_order => 50,
  p_version_note => 'Added Florida News Exchange',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"text":"The ","type":"text"},{"text":"Sources","type":"text","marks":[{"type":"link","attrs":{"href":"/log/sources"}}]},{"text":" tab holds the outside feeds On Air reads. It opens on one card per source, showing whether its saved data is current, when it was last updated, and what it holds. Select a card's ","type":"text"},{"text":"Open","type":"text","marks":[{"type":"bold"}]},{"text":" button to go to that source's page, and ","type":"text"},{"text":"← Sources","type":"text","marks":[{"type":"bold"}]},{"text":" to come back.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"What the cards say","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Up to date","type":"text","marks":[{"type":"bold"}]},{"text":": the saved data is inside its normal refresh window.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Stale","type":"text","marks":[{"type":"bold"}]},{"text":": the saved data is older than that, or the last refresh failed. What was saved is still shown.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Not fetched yet","type":"text","marks":[{"type":"bold"}]},{"text":": nothing has been read from this source so far.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Not configured","type":"text","marks":[{"type":"bold"}]},{"text":": the portal has no access set up for this source yet.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"NPR","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On the NPR page, choose a program and a show date, then select ","type":"text"},{"text":"Switch","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The table lists each story's estimated air time (marked with “~”, since NPR doesn't supply exact times), title, teaser, and length.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Refresh","type":"text","marks":[{"type":"bold"}]},{"text":" to pull the latest episode data.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"The NPR card reports the most recently read episode. NPR is read one program and date at a time, so it is refreshed from the NPR page rather than the card.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Weather","type":"text"}]},{"type":"paragraph","content":[{"text":"The weather page shows the current forecast: any hazards, a short outlook, live-read and condensed text for on air, and the underlying details. Select ","type":"text"},{"text":"Refresh","type":"text","marks":[{"type":"bold"}]},{"text":" on the page or on the weather card to force an update.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Florida News Exchange"}]},{"type":"paragraph","content":[{"type":"text","text":"This page lists the stories other Florida stations shared through PRX in the last 24 hours, newest first. A wrap and its cut are listed together. Each version has a player, a download, and a link to its page on PRX."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The feed description is often only a summary. The full script can be on the story's PRX page: select "},{"type":"text","text":"Open on PRX","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A hold note from the feed, such as Hold until 10/8, appears beside the story. It is there for you to follow; the portal does not enforce it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Add to library","marks":[{"type":"bold"}]},{"type":"text","text":" to open the new content item form with the title, the type News, and a summary already filled in. The summary holds the description, any hold note and the PRX link. Paste the script, save, then add its components (live intro, recorded audio, outro) on the item's page, as for any library item."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audio is not copied into the portal. Load it into DAD to air it. The links in the feed expire after an hour, so if a player will not play, reload the page."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sources refresh themselves when you open them and their data is past its window. Refresh is a manual option, not something you need to do routinely.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A fetch failure shows as a plain message, with whatever was last read still on screen. No page goes blank because of a temporary outage.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"NPR's estimated times need a rundown to already exist for that program and date. Without one, the table has nothing to anchor its estimates to.","type":"text"}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-09-log-florida-news-exchange',
  p_tool_key => 'log',
  p_released_on => '2026-10-09',
  p_title => 'Florida News Exchange stories in Sources',
  p_guide_slugs => array['log-npr-and-weather'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Sources","marks":[{"type":"bold"}]},{"type":"text","text":" tab now has a Florida News Exchange card. It lists the stories other Florida stations shared through PRX in the last 24 hours, with a wrap and its cut together, each with its audio, a download, and a link to its PRX page. The feed's description is often only a summary, so the full script may be on the PRX page. Select "},{"type":"text","text":"Add to library","marks":[{"type":"bold"}]},{"type":"text","text":" to open the new content item form with the title and description filled in, then add the script and components as you would for any item."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-09-log-wrap-up-after-the-program',
  p_tool_key => 'log',
  p_released_on => '2026-10-09',
  p_title => 'Wrap up appears when the program ends',
  p_guide_slugs => array['log-daily-rundown-and-console'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On a rundown, the Wrap up panel in the sidebar now appears once the program's shift has ended, instead of showing the whole time the broadcast is on. A rundown that has already been submitted still shows it."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-daily-rundown-and-console',
  p_tool_key => 'log',
  p_title => 'Running the daily rundown and host console',
  p_summary => 'Generate a rundown, fill its breaks, and run it live — one screen for building and broadcasting.',
  p_screen_keys => array['log.rundown'],
  p_sort_order => 40,
  p_version_note => 'Wrap up appears when the program ends',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"text":"A ","type":"text"},{"text":"rundown's screen","type":"text","marks":[{"type":"link","attrs":{"href":"/log"}}]},{"text":" does double duty: build it ahead of time, then run the same screen live once you start the broadcast.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Generate and fill","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On the Today screen, select ","type":"text"},{"text":"Generate","type":"text","marks":[{"type":"bold"}]},{"text":" next to a program that doesn't have a rundown yet for that date.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Open it. Hover the thin line between items in a break to fill it — search the eligible content library, add today's weather, or create a one-off live read right there.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Go live","type":"text"}]},{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Start broadcast","type":"text","marks":[{"type":"bold"}]},{"text":" in the sidebar. The current break is highlighted, and the mid-broadcast controls appear on every unconfirmed item across the whole rundown.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"During the broadcast","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On an underwriting credit, confirm it with ","type":"text"},{"text":"Yes, aired","type":"text","marks":[{"type":"bold"}]},{"text":" or ","type":"text"},{"text":"No — flag it","type":"text","marks":[{"type":"bold"}]},{"text":" (choosing a reason). Ordinary content has no aired/missed confirmation — only a credit carries that obligation.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Move any item with its ","type":"text"},{"text":"⋮","type":"text","marks":[{"type":"bold"}]},{"text":" menu, or drag it to a different break.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Wrap up","type":"text"}]},{"type":"paragraph","content":[{"text":"Once the program's shift has ended, a Wrap-up panel appears in the sidebar and lists anything unresolved. Before then it is hidden, to leave room. Optionally attest or mark items aired in bulk, then select ","type":"text"},{"text":"Submit rundown","type":"text","marks":[{"type":"bold"}]},{"text":" — a checkpoint, not a lock. A correction after submission works exactly the same as before it.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Aired, missed, and move actions are queued on your device and sent once you're back online — a dropped connection doesn't lose them.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Adding content to a break needs a live connection, since it's a request to the server rather than a queued action.","type":"text"}]}]}]}]}$body$
);
